  await cdp.send\('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] }\);
  await page.waitForTimeout\(150\);
  const dragOpened = await page.evaluate\(\(\) => !document.getElementById\('gameScreen'\).hidden\);
  await page.evaluate\(\(\) => window.openShelf\(\)\); await page.waitForTimeout\(80\);
  await page.mouse.click\(pt.x, pt.y, { button: 'right' }\);
  await page.waitForTimeout\(120\);
  const rightOpened = await page.evaluate\(\(\) => !document.getElementById\('gameScreen'\).hidden\);
  await page.evaluate\(\(\) => window.openShelf\(\)\); await page.waitForTimeout\(80\);
  await page.mouse.click\(pt.x, pt.y, { button: 'middle' }\);
  await page.waitForTimeout\(120\);
  const middleOpened = await page.evaluate\(\(\) => !document.getElementById\('gameScreen'\).hidden\);
  console.log\(JSON.stringify\({ box, pt, hit, F2_dragOpenedGame: dragOpened, rightOpened, middleOpened }, null, 1\)\);
  await browser.close\(\);
}\)\(\);
EOF
